INSERT INTO "static_pages" ("id", "path", "kind", "title", "eyebrow", "intro", "summary", "sections", "sort_order", "status", "published_at", "updated_at")
VALUES (gen_random_uuid(), 'du-an/sun-symphony-residence/can-ho-studio-1pn-1-2pn-3pn', 'PAGE', 'Căn hộ tại Sun Symphony Residence', 'SUN SYMPHONY · CĂN HỘ', 'Căn hộ Studio đến 3 phòng ngủ tại phân khu cao tầng The Symphony, trong khu đô thị 8 ha bên sông Hàn.', 'Studio đến 3 phòng ngủ tại The Symphony.', '[{"heading": "Các loại căn", "body": "- Studio\n- Căn 1+1 phòng ngủ\n- Căn 2 phòng ngủ\n- Căn 3 phòng ngủ\n- Dual Front và Garden House\n\nCăn 1–3 phòng ngủ có diện tích khoảng 35,8–112,1 m². Diện tích chỉ để tham khảo, có thể khác nhau giữa các tòa."}, {"heading": "Vị trí và quy mô", "body": "Dự án rộng khoảng 8 ha tại phường Sơn Trà, Đà Nẵng, có mặt tiền trực tiếp sông Hàn. Khu cao tầng The Symphony nằm cùng khu thấp tầng The Sonata."}, {"heading": "Tiện ích dành cho cư dân", "body": "- Bể bơi vô cực ngoài trời hướng sông Hàn và bể bơi bốn mùa trong nhà\n- Công viên Central Park 5.000 m²\n- Phòng gym, spa, kids club\n- Vườn nướng BBQ\n- Đường dạo bộ ven sông Hàn"}, {"heading": "Nguồn thông tin", "body": "Thông tin tổng hợp từ trang của Sun Property, CafeLand, VietnamFinance và The Leader, có thể thay đổi theo chủ đầu tư. Đất Vàng Group sẽ xác nhận lại khi tư vấn."}]'::jsonb, 0, 'PUBLISHED', CURRENT_TIMESTAMP AT TIME ZONE 'UTC', CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
ON CONFLICT ("path") DO NOTHING;

INSERT INTO "static_pages" ("id", "path", "kind", "title", "eyebrow", "intro", "summary", "sections", "sort_order", "status", "published_at", "updated_at")
VALUES (gen_random_uuid(), 'du-an/sun-symphony-residence/penthouse-sky-villa', 'PAGE', 'Penthouse và Sky Villa tại Sun Symphony Residence', 'SUN SYMPHONY · PENTHOUSE', 'Hai dòng sản phẩm trong danh mục của Sun Symphony Residence, dự án bên sông Hàn.', 'Penthouse và Sky Villa của dự án.', '[{"heading": "Penthouse", "body": "Penthouse có trong danh mục sản phẩm của dự án. Theo VietnamFinance, căn Penthouse và Garden House có bể bơi riêng để ngắm thành phố."}, {"heading": "Sky Villa", "body": "Sky Villa có trong danh mục sản phẩm do Sun Property công bố."}, {"heading": "Thông tin đang cập nhật", "body": "Số lượng, diện tích và giá của Penthouse, Sky Villa chưa có trong các nguồn chúng tôi tham khảo. Hãy liên hệ để được kiểm tra theo bảng hàng mới nhất."}, {"heading": "Tiện ích dành cho cư dân", "body": "- Bể bơi vô cực ngoài trời hướng sông Hàn và bể bơi bốn mùa trong nhà\n- Công viên Central Park 5.000 m²\n- Phòng gym, spa, kids club\n- Vườn nướng BBQ\n- Đường dạo bộ ven sông Hàn"}, {"heading": "Nguồn thông tin", "body": "Thông tin tổng hợp từ trang của Sun Property, CafeLand, VietnamFinance và The Leader, có thể thay đổi theo chủ đầu tư. Đất Vàng Group sẽ xác nhận lại khi tư vấn."}]'::jsonb, 1, 'PUBLISHED', CURRENT_TIMESTAMP AT TIME ZONE 'UTC', CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
ON CONFLICT ("path") DO NOTHING;

INSERT INTO "static_pages" ("id", "path", "kind", "title", "eyebrow", "intro", "summary", "sections", "sort_order", "status", "published_at", "updated_at")
VALUES (gen_random_uuid(), 'du-an/sun-symphony-residence/nha-pho-biet-thu', 'PAGE', 'Nhà phố và biệt thự tại Sun Symphony Residence', 'SUN SYMPHONY · THE SONATA', 'Phân khu thấp tầng The Sonata ven sông Hàn, gồm nhà phố, biệt thự song lập và đơn lập.', 'Phân khu thấp tầng The Sonata ven sông Hàn.', '[{"heading": "Nhà phố", "body": "- Khoảng 180 căn, cao 3–5 tầng\n- Diện tích khoảng 108–320 m²\n- Mặt tiền 6–10 m\n- Công năng linh hoạt: để ở, làm cửa tiệm hoặc khách sạn\n\nThiết kế mái ngói đỏ, mái vòm, ô cửa lớn và hiên rộng."}, {"heading": "Biệt thự", "body": "- Khoảng 20 căn mặt sông, gồm biệt thự song lập và đơn lập\n- Diện tích khoảng 345–380 m²"}, {"heading": "Thương mại trong phân khu", "body": "Các tiểu khu thương mại nằm giữa khu nhà phố và khu biệt thự, có spa, làm đẹp, ẩm thực và café."}, {"heading": "Nguồn thông tin", "body": "Thông tin tổng hợp từ trang của Sun Property, CafeLand, VietnamFinance và The Leader, có thể thay đổi theo chủ đầu tư. Đất Vàng Group sẽ xác nhận lại khi tư vấn."}]'::jsonb, 2, 'PUBLISHED', CURRENT_TIMESTAMP AT TIME ZONE 'UTC', CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
ON CONFLICT ("path") DO NOTHING;

INSERT INTO "static_pages" ("id", "path", "kind", "title", "eyebrow", "intro", "summary", "sections", "sort_order", "status", "published_at", "updated_at")
VALUES (gen_random_uuid(), 'du-an/cora-tower/studio-1pn-1pn-1', 'PAGE', 'Studio, 1PN và 1PN+1 tại Cora Tower', 'CORA TOWER · CĂN NHỎ', 'Các căn diện tích gọn tại Cora Tower, trung tâm khu đô thị Sun NeO City ở phía Nam Đà Nẵng.', 'Các căn diện tích gọn tại Cora Tower.', '[{"heading": "Các loại căn", "body": "- Studio: khoảng 34,7 m²\n- Căn 1 phòng ngủ và 1PN+1: khoảng 43,7–48,9 m²\n\nDiện tích chỉ để tham khảo, có thể khác nhau giữa các tòa."}, {"heading": "Vị trí", "body": "Hai mặt tiền đường Nguyễn Phước Lan và đường 29/3, tại trung tâm Sun NeO City.\n\n- Sân bay quốc tế Đà Nẵng: khoảng 5–10 phút\n- Biển Mỹ Khê, Non Nước: khoảng 10 phút\n- Hội An: khoảng 30–35 phút"}, {"heading": "Tiện ích trong tòa", "body": "- Hồ bơi 8x30 m trên tầng thượng\n- Phòng gym, spa, steam, sauna\n- Kid''s Club và phòng sinh hoạt cộng đồng\n- Khu BBQ, vườn cảnh quan"}, {"heading": "Nguồn thông tin", "body": "Thông tin tổng hợp từ trang của Sun Property, CafeLand và Tuổi Trẻ, có thể thay đổi theo chủ đầu tư. Đất Vàng Group sẽ xác nhận lại khi tư vấn."}]'::jsonb, 0, 'PUBLISHED', CURRENT_TIMESTAMP AT TIME ZONE 'UTC', CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
ON CONFLICT ("path") DO NOTHING;

INSERT INTO "static_pages" ("id", "path", "kind", "title", "eyebrow", "intro", "summary", "sections", "sort_order", "status", "published_at", "updated_at")
VALUES (gen_random_uuid(), 'du-an/cora-tower/can-ho-2pn-3pn', 'PAGE', 'Căn hộ 2PN và 3PN tại Cora Tower', 'CORA TOWER · CĂN GIA ĐÌNH', 'Các căn 2 và 3 phòng ngủ trong hai tòa tháp 25 tầng với khoảng 1.281 căn hộ của Cora Tower.', 'Căn 2 và 3 phòng ngủ tại Cora Tower.', '[{"heading": "Các loại căn", "body": "- Căn 2 phòng ngủ: khoảng 58–87,1 m²\n- Căn 3 phòng ngủ: khoảng 102,8 m²\n\nDiện tích chỉ để tham khảo, có thể khác nhau giữa các tòa."}, {"heading": "Quy mô", "body": "- Tổng diện tích 4.165 m²\n- 2 tòa tháp, cao 25 tầng nổi và 2 tầng hầm\n- Khoảng 1.281 căn hộ"}, {"heading": "Tiện ích quanh dự án", "body": "Theo CafeLand, cư dân khu đô thị có Hype Park 50 ha, Sport Park với sân tennis và sân đa năng, Marina Park và Dòng sông ánh sáng. Các công viên này thuộc khu đô thị, không phải tiện ích riêng của tòa."}, {"heading": "Nguồn thông tin", "body": "Thông tin tổng hợp từ trang của Sun Property, CafeLand và Tuổi Trẻ, có thể thay đổi theo chủ đầu tư. Đất Vàng Group sẽ xác nhận lại khi tư vấn."}]'::jsonb, 1, 'PUBLISHED', CURRENT_TIMESTAMP AT TIME ZONE 'UTC', CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
ON CONFLICT ("path") DO NOTHING;

INSERT INTO "static_pages" ("id", "path", "kind", "title", "eyebrow", "intro", "summary", "sections", "sort_order", "status", "published_at", "updated_at")
VALUES (gen_random_uuid(), 'du-an/cora-tower/penthouse-shophouse', 'PAGE', 'Penthouse và Shophouse tại Cora Tower', 'CORA TOWER · PENTHOUSE & SHOPHOUSE', 'Penthouse ở tầng cao nhất và dãy shophouse ở chân tòa tháp, hai mặt tiền Nguyễn Phước Lan và 29/3.', 'Penthouse tầng cao nhất, shophouse khối đế.', '[{"heading": "Penthouse", "body": "Penthouse nằm ở tầng cao nhất của tòa tháp. CafeLand có nêu loại Duplex khoảng 200 m²."}, {"heading": "Shophouse", "body": "Dãy shophouse khối đế nằm ngay chân tòa tháp, tại dự án có hai mặt tiền đường Nguyễn Phước Lan và đường 29/3."}, {"heading": "Thông tin đang cập nhật", "body": "Số lượng, diện tích và giá của Penthouse, Shophouse chưa có trong các nguồn chúng tôi tham khảo. Hãy liên hệ để được kiểm tra theo bảng hàng mới nhất."}, {"heading": "Nguồn thông tin", "body": "Thông tin tổng hợp từ trang của Sun Property, CafeLand và Tuổi Trẻ, có thể thay đổi theo chủ đầu tư. Đất Vàng Group sẽ xác nhận lại khi tư vấn."}]'::jsonb, 2, 'PUBLISHED', CURRENT_TIMESTAMP AT TIME ZONE 'UTC', CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
ON CONFLICT ("path") DO NOTHING;
